function esc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function db():PDO {static $p=null;if($p)return $p; $dir=__DIR__.'/data';if(!is_dir($dir))mkdir($dir,0700,true); $p=new PDO('sqlite:'.$dir.'/odonto_em_dia.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec('PRAGMA busy_timeout=5000');$p->exec('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP)');$p->exec('CREATE TABLE IF NOT EXISTS clinics(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,name TEXT NOT NULL,cnpj TEXT DEFAULT \'\',city TEXT DEFAULT \'\',state TEXT DEFAULT \'\',rt_name TEXT DEFAULT \'\',rt_cro TEXT DEFAULT \'\',chairs INTEGER DEFAULT 1,has_xray INTEGER DEFAULT 0,has_sedation INTEGER DEFAULT 0,sterilization TEXT DEFAULT \'interna\',created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id))');$p->exec('CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY,clinic_id INTEGER NOT NULL,group_no INTEGER NOT NULL,status TEXT DEFAULT \'pendente\',responsible TEXT DEFAULT \'\',due_date TEXT DEFAULT \'\',notes TEXT DEFAULT \'\',updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(clinic_id,group_no))');$p->exec('CREATE TABLE IF NOT EXISTS checks(id INTEGER PRIMARY KEY,clinic_id INTEGER NOT NULL,code TEXT NOT NULL,status TEXT DEFAULT \'nao_avaliado\',notes TEXT DEFAULT \'\',UNIQUE(clinic_id,code))');return $p;}
function groups():array{return [1=>'Licenciamento e regularização',2=>'Responsabilidades técnicas e equipe',3=>'Estrutura física e instalações',4=>'Equipamentos e manutenção',5=>'Água e condições ambientais',6=>'Higienização e limpeza',7=>'Biossegurança e EPIs',8=>'Processamento de produtos para saúde',9=>'Resíduos de serviços de saúde',10=>'Segurança do paciente',11=>'Medicamentos e insumos',12=>'Controle de infecções',13=>'Prontuários e registros',14=>'Radiologia (quando aplicável)',15=>'Sedação e urgências (quando aplicável)',16=>'Capacitação e treinamento',17=>'Monitoramento e melhoria contínua'];}
// Os grupos acima são categorias de trabalho para organização da plataforma; não são transcrição literal do artigo 113.
function checks():array{return ['A01'=>'Licença sanitária e documentos de regularização','A02'=>'Responsável técnico identificado e documentado','A03'=>'Rotinas de higienização registradas','A04'=>'Controle de esterilização documentado','A05'=>'Rastreabilidade dos materiais processados','A06'=>'PGRSS avaliado e atualizado','A07'=>'Registros de capacitação da equipe','A08'=>'Manutenção dos equipamentos documentada','A09'=>'Registros de incidentes e ações corretivas','A10'=>'Protocolos de atendimento de urgência revisados','A11'=>'Condições de armazenamento verificadas','A12'=>'Registros de controle de qualidade disponíveis','A13'=>'Rotina de avaliação de riscos registrada','A14'=>'Prontuários organizados e protegidos','A15'=>'Documentação de radiologia verificada, se aplicável'];}
function csrf():string {if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function token():string{return '<input type="hidden" name="csrf" value="'.esc(csrf()).'">';}
function redirect(string $url='?'):never{header('Location: '.$url, true,303);exit;}
